<script setup lang="ts">
import {computed} from 'vue';
import {AlertCircle,ArrowRight,FileDiff,ShieldCheck} from 'lucide-vue-next';
type Item=Record<string,any>;
const props=defineProps<{approval:Item;tenants:Item[]}>();
const action=computed(()=>props.approval.payload?.action??{});
const revision=computed(()=>props.approval.payload?.revision??{});
const info=computed(()=>{const data=revision.value.info?.data;const payload=data?.payload??data??{};return payload.body??payload;});
const tenant=computed(()=>props.tenants.find(t=>String(t.id)===String(revision.value.tenant_id))?.name??revision.value.tenant_id);
const deskId=computed(()=>action.value.desk??info.value.deskId??info.value.desk_id??(typeof info.value._state==='object'?info.value._state?.deskId:null));
const scheduleAction=computed(()=>String(action.value.resource??'').startsWith('schedule:'));
function frequency(trigger:Item){const n=Number(trigger.period??1);return ({Minute:'A cada '+n+' minuto(s)',Hour:'A cada '+n+' hora(s)',Day:n===1?'Diariamente':'A cada '+n+' dias'} as Record<string,string>)[trigger.type]??'Frequência a conferir';}
const deleted=computed(()=>action.value.action==='delete_draft');
const publish=computed(()=>String(action.value.action??'').startsWith('publish'));
const textDiff=computed(()=>{const data=revision.value.changes?.data??{};return data.workingVsServer?.unified??data.workingVsState?.unified??'';});
const changedLines=computed(()=>String(textDiff.value).split('\n').filter(line=>/^[+-](?![+-])/.test(line)));
const excerpt=computed(()=>changedLines.value.slice(0,40).map(line=>line.length>1000?line.slice(0,1000)+'…':line).join('\n').slice(0,12000));
</script>
<template><div class="approval-review"><dl><div><dt>Tenant</dt><dd>{{tenant}}</dd></div><div><dt>Recurso</dt><dd>{{info.nome||info.name||action.resource}} <small v-if="info.nome||info.name">{{action.resource}}</small></dd></div><div><dt>Destino</dt><dd>{{scheduleAction?'Agente #'+(revision.schedule?.tokenId??info.tokenId??'a conferir'):(deskId?'Mesa #'+deskId:'Minha Mesa · rascunho')}}</dd></div><div v-if="info.cloned_from"><dt>Origem da cópia</dt><dd>Aplicação #{{info.cloned_from}}</dd></div></dl><div v-if="deleted" class="review-impact"><AlertCircle :size="18"/><p>Este rascunho será excluído. O sistema confirma que ele foi criado por este projeto e preserva uma revisão local antes da remoção. A aplicação original e as fontes não são removidas.</p></div><div v-else-if="publish" class="review-impact"><AlertCircle :size="18"/><p>A publicação compartilha o recurso na mesa indicada. Se esta cópia for publicada na mesa da aplicação original, ela poderá substituir a versão existente. Confira o destino antes de autorizar.</p></div><div v-if="revision.schedule" class="review-changes"><strong>Agenda a executar</strong><p>{{revision.schedule.nome}} · {{revision.schedule.ativo?'Ativa':'Inativa'}} · {{revision.schedule.timezone}}</p><p v-for="flow in revision.schedule.flows" :key="flow.flow_etl_id">Fonte #{{flow.flow_etl_id}} · {{flow.context}}</p><p v-for="(trigger,index) in revision.schedule.triggers" :key="index">{{frequency(trigger)}}<span v-if="trigger.start_when"> · início {{trigger.start_when}}</span></p></div><div v-if="excerpt" class="review-changes"><strong><FileDiff :size="16"/>Alterações propostas</strong><pre>{{excerpt}}</pre><p v-if="changedLines.length>40">Mostrando parte das alterações. Consulte a revisão técnica completa abaixo.</p></div><p v-else-if="action.action==='run_schedule'" class="review-impact">Esta execução iniciará uma carga real de dados. O resultado só será considerado bem-sucedido após a conclusão confirmada no BI.</p><p v-else-if="action.action==='resume_schedule'" class="review-impact">A agenda passará a executar automaticamente. Confira fontes, frequência e agente na revisão técnica.</p><p v-else-if="!deleted&&!publish" class="review-impact">Confira o recurso e o destino. Esta autorização vale somente para a revisão apresentada.</p><details><summary>Ver revisão técnica completa</summary><pre>{{JSON.stringify(approval.payload,null,2)}}</pre></details></div></template>
<style scoped>.approval-review{background:#fff;border:1px solid #e4e8f0;border-radius:10px;padding:18px;margin:18px 0}.approval-review dl{display:grid;grid-template-columns:1fr 1.4fr 1fr;gap:18px;margin:0 0 16px}.approval-review dt{font-size:11px;color:#68758a;margin-bottom:5px}.approval-review dd{font-size:13px;font-weight:600;margin:0;color:#20314c}.approval-review small{display:block;font-weight:400;color:#758198;margin-top:4px}.review-impact{display:flex;gap:9px;font-size:12px;line-height:1.7;color:#6c5633;background:#fff8eb;border-radius:7px;padding:12px}.review-impact p{margin:0}.review-impact svg{flex-shrink:0;margin-top:3px}.review-changes>strong{display:flex;align-items:center;gap:8px;font-size:12px;color:#314a71;margin:14px 0}.approval-review pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:240px;overflow:auto;font-size:11px;background:#f4f7fb;color:#34425a;padding:13px;border-radius:6px}.approval-review details{margin-top:16px}.approval-review summary{cursor:pointer;color:#65758b;font-size:12px}.approval-review details pre{max-height:320px}.review-changes>p{font-size:12px;color:#8b6418}@media(max-width:700px){.approval-review dl{grid-template-columns:1fr}}</style>
